  static const int CONTACTS_ERROR_INVALID_PARAMETER = -22;

  /// < FS Full
  static const int CONTACTS_ERROR_FILE_NO_SPACE = -28;

  /// < Permission denied
  static const int CONTACTS_ERROR_PERMISSION_DENIED = -13;

  /// < Not supported
  static const int CONTACTS_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Requested data does not exist
  static const int CONTACTS_ERROR_NO_DATA = -61;

  /// < Database table locked or file locked
  static const int CONTACTS_ERROR_DB_LOCKED = -33619839;

  /// < Unknown DB error
  static const int CONTACTS_ERROR_DB = -33619809;

  /// < IPC server is not available
  static const int CONTACTS_ERROR_IPC_NOT_AVALIABLE = -33619791;

  /// < Unknown IPC error
  static const int CONTACTS_ERROR_IPC = -33619777;

  /// < Internal system module error
  static const int CONTACTS_ERROR_SYSTEM = -33619729;

  /// < Implementation Error, Temporary Use
  static const int CONTACTS_ERROR_INTERNAL = -33619713;
}

